import{_ as t,o as s,c as r,a6 as n}from"./chunks/framework.QBF2cGGQ.js";const u=JSON.parse('{"title":"21 · Python 与 AI 生态","description":"","frontmatter":{},"headers":[],"relativePath":"guide/21-python.md","filePath":"guide/21-python.md","lastUpdated":1793329740000}'),a={name:"guide/21-python.md"};function i(e,o,p,l,c,d){return s(),r("div",null,[...o[0]||(o[0]=[n('<h1 id="_21-·-python-与-ai-生态" tabindex="-1">21 · Python 与 AI 生态 <a class="header-anchor" href="#_21-·-python-与-ai-生态" aria-label="Permalink to &quot;21 · Python 与 AI 生态&quot;">​</a></h1><blockquote><p><strong>投入权重：8%</strong> · 补的一章。上一版这块只有一句话，太薄。</p><p>先说结论：<strong>要不要学 Python，取决于你投什么岗</strong>。投 AI 应用/全栈，TS 一条路走通更省力；投 LLM 工程、算法应用、或者要读开源实现，Python 是硬门槛。两条清单在这点上打架（一份说&quot;主语言定 Python&quot;，一份推荐 NestJS 全家桶），我的判断是：<strong>后端主语言选一个，但 Python 必须能读能改</strong>。</p></blockquote><h2 id="为什么绕不开" tabindex="-1">为什么绕不开 <a class="header-anchor" href="#为什么绕不开" aria-label="Permalink to &quot;为什么绕不开&quot;">​</a></h2><p>不是因为它更好，是因为生态在那。RAG 的评测工具（RAGAS）、微调框架（LLaMA-Factory、Unsloth）、推理引擎（vLLM、SGLang）、文档解析（MinerU、unstructured）、数据处理（pandas），全是 Python 优先。你在 TS 里找对应库，要么没有，要么是薄封装。</p><p><strong>但&quot;能读能改&quot;和&quot;用它做主后端&quot;是两回事。</strong> 前者两三周够，后者要几个月。建议先做到前者。</p><h2 id="语言基础" tabindex="-1">语言基础 <a class="header-anchor" href="#语言基础" aria-label="Permalink to &quot;语言基础&quot;">​</a></h2><ul><li><strong>基础语法与缩进</strong> <span class="prio prio-must">必须</span> — 没有大括号，靠缩进。看起来简单，但混用 tab/space 会报错。</li><li><strong>动态类型与类型注解</strong> <span class="prio prio-must">必须</span> — 注解不强制检查，但 FastAPI/Pydantic 靠它做校验和文档。<strong>这是 Python 里最重要的&quot;工程化&quot;习惯</strong>。</li><li><strong>list / dict / tuple / set</strong> <span class="prio prio-must">必须</span> — dict 是有序的（3.7+），tuple 不可变可做 key。</li><li><strong>切片与推导式</strong> <span class="prio prio-must">必须</span> — <code>a[1:5:2]</code>、<code>[x*2 for x in xs if x&gt;0]</code>。读别人代码天天见。</li><li><strong>函数与默认参数陷阱</strong> <span class="prio prio-must">必须</span> — <code>def f(a=[])</code> 的可变默认值会跨调用共享，这是经典 bug。</li><li><strong>装饰器</strong> <span class="prio prio-imp">重要</span> — <code>@app.get</code>、<code>@pytest.fixture</code>、<code>@retry</code> 全是装饰器。要能读懂闭包实现的原理。</li><li><strong>类与 <code>__init__</code> / <code>__repr__</code> / <code>__eq__</code></strong> <span class="prio prio-imp">重要</span> — 不需要精通元类，但要会写 dataclass 风格的类。</li><li><strong>dataclass</strong> <span class="prio prio-must">必须</span> — <code>@dataclass</code> 自动生成 init/repr/eq。<strong>比手写类省一半代码</strong>，配置对象、消息结构都用它。</li><li><strong>Generator 与 <code>yield</code></strong> <span class="prio prio-must">必须</span> — 流式响应、批量处理的核心。理解&quot;惰性求值&quot;。</li><li><strong><code>async</code> / <code>await</code> / <code>asyncio</code></strong> <span class="prio prio-must">必须</span> — LLM 调用是 IO 密集，必须异步。<code>asyncio.gather</code> 并发、<code>Semaphore</code> 限流。</li><li><strong>异常处理</strong> <span class="prio prio-must">必须</span> — <code>try/except/else/finally</code>、自定义异常、<code>raise ... from</code>。<strong>别写裸 <code>except:</code></strong>，会吞掉 KeyboardInterrupt。</li><li><strong>Context Manager（<code>with</code>）</strong> <span class="prio prio-imp">重要</span> — 文件、连接、锁。自己写要会 <code>__enter__</code>/<code>__exit__</code> 或 <code>@contextmanager</code>。</li><li><strong>pathlib</strong> <span class="prio prio-imp">重要</span> — 路径操作用它，别拼字符串。</li><li><strong>json 与序列化</strong> <span class="prio prio-must">必须</span> — <code>json.dumps(ensure_ascii=False)</code> 不然中文变 <code>\\uXXXX</code>。</li><li><strong>logging</strong> <span class="prio prio-must">必须</span> — 别用 print。配置 handler、formatter、level。</li><li><strong>pytest</strong> <span class="prio prio-must">必须</span> — fixture、参数化、mock。评测脚本本质就是 pytest。</li></ul><h2 id="工具链" tabindex="-1">工具链 <a class="header-anchor" href="#工具链" aria-label="Permalink to &quot;工具链&quot;">​</a></h2><ul><li><strong>uv（推荐）/ pip</strong> <span class="prio prio-must">必须</span> — uv 是目前最快的包管理器，能替代 pip + venv + pyenv。<strong>新项目直接上 uv</strong>。</li><li><strong>venv 虚拟环境</strong> <span class="prio prio-must">必须</span> — 每个项目独立环境，否则依赖冲突无解。</li><li><strong>pyproject.toml</strong> <span class="prio prio-must">必须</span> — 现代 Python 项目的标准配置，替代 setup.py。</li><li><strong>Ruff</strong> <span class="prio prio-must">必须</span> — lint + format 二合一，比 flake8+black+isort 快几十倍。</li><li><strong>FastAPI</strong> <span class="prio prio-must">必须</span> — 异步、类型驱动、自动生成 OpenAPI。<strong>AI 服务后端首选</strong>。</li><li><strong>Pydantic</strong> <span class="prio prio-must">必须</span> — 运行时校验 + 类型转换，作用等同于 TS 的 zod。<strong>LLM 结构化输出必用</strong>。</li><li><strong>Uvicorn</strong> <span class="prio prio-must">必须</span> — ASGI 服务器。生产用 gunicorn + uvicorn worker。</li><li><strong>mypy / pyright</strong> <span class="prio prio-imp">重要</span> — 静态类型检查。有注解不检查等于白写。</li></ul><h2 id="数据处理" tabindex="-1">数据处理 <a class="header-anchor" href="#数据处理" aria-label="Permalink to &quot;数据处理&quot;">​</a></h2><ul><li><strong>NumPy 基础</strong> <span class="prio prio-imp">重要</span> — 数组、广播、矩阵运算。<strong>理解向量运算才看得懂 embedding 相似度</strong>。</li><li><strong>pandas</strong> <span class="prio prio-must">必须</span> — DataFrame、groupby、merge、apply。处理评测结果、成本统计、文档元数据都靠它。</li><li><strong>CSV / JSON / Parquet</strong> <span class="prio prio-imp">重要</span> — Parquet 比 CSV 小且快，大数据集用它。</li><li><strong>文档解析库</strong> <span class="prio prio-must">必须</span> — PyMuPDF、python-docx、openpyxl、BeautifulSoup。RAG 的数据入口。</li><li><strong>数据清洗</strong> <span class="prio prio-must">必须</span> — 去重、去噪、编码修正、全半角统一。<strong>这步做不好后面全白费</strong>。</li><li><strong>Jupyter Notebook</strong> <span class="prio prio-imp">重要</span> — 探索数据、调 prompt、跑评测时用它。<strong>但别把 notebook 当生产代码</strong>。</li><li><strong>Matplotlib / seaborn</strong> <span class="prio prio-opt">选学</span> — 画指标曲线。简单够用就行，展示交给前端。</li></ul><h2 id="ai-生态" tabindex="-1">AI 生态 <a class="header-anchor" href="#ai-生态" aria-label="Permalink to &quot;AI 生态&quot;">​</a></h2><ul><li><strong>Hugging Face Hub</strong> <span class="prio prio-must">必须</span> — 模型/数据集的家。会用 <code>hf</code> CLI 下载、看 model card。</li><li><strong>Transformers</strong> <span class="prio prio-imp">重要</span> — <code>AutoModel</code> / <code>AutoTokenizer</code> / <code>pipeline</code>。<strong>能跑通推理就够</strong>，不必读源码。</li><li><strong>Datasets</strong> <span class="prio prio-imp">重要</span> — 高效加载大数据集，支持流式。</li><li><strong>Tokenizers</strong> <span class="prio prio-imp">重要</span> — 算 token 数、看分词结果。<strong>调成本必用</strong>。</li><li><strong>Sentence Transformers</strong> <span class="prio prio-must">必须</span> — 跑 embedding 和 rerank 模型的标准方式。bge 系列都走这个。</li><li><strong>PyTorch 入门</strong> <span class="prio prio-opt">选学</span> — 理解 tensor、device、<code>.to(&#39;cuda&#39;)</code>、推理时 <code>torch.no_grad()</code>。<strong>不必会训练</strong>。</li><li><strong>模型推理 API</strong> <span class="prio prio-must">必须</span> — 本地加载模型跑推理、批量推理、显存管理。</li></ul><h2 id="和-ts-的分工-这条最重要" tabindex="-1">和 TS 的分工（这条最重要） <a class="header-anchor" href="#和-ts-的分工-这条最重要" aria-label="Permalink to &quot;和 TS 的分工（这条最重要）&quot;">​</a></h2><p>不要两个都学一半。明确分工：</p><table tabindex="0"><thead><tr><th>层</th><th>语言</th><th>理由</th></tr></thead><tbody><tr><td>前端 / BFF</td><td>TypeScript</td><td>你的存量，生态成熟</td></tr><tr><td>API 网关 / 业务服务</td><td>TS 或 Python，<strong>选一个</strong></td><td>团队用什么就用什么</td></tr><tr><td>RAG / 评测 / 数据处理</td><td><strong>Python</strong></td><td>生态只有这边有</td></tr><tr><td>微调 / 推理</td><td><strong>Python</strong></td><td>无选择</td></tr><tr><td>Agent 编排</td><td>看框架</td><td>LangGraph 两边都有，Vercel AI SDK 只有 TS</td></tr></tbody></table><p><strong>建议</strong>：主后端用 TS（你的迁移成本最低），但把 RAG 的评测、数据处理、微调脚本用 Python 写。两个服务之间用 HTTP 或队列通信。</p><h2 id="学习边界" tabindex="-1">学习边界 <a class="header-anchor" href="#学习边界" aria-label="Permalink to &quot;学习边界&quot;">​</a></h2><p>不要一上来研究 CUDA、自动求导、分布式训练。<strong>你的目标是&quot;能读懂并修改常见的 Python AI 应用代码&quot;</strong>，具体是：</p><ul><li>能看懂一个 RAG 项目的目录结构和主流程</li><li>能改一个评测脚本的指标计算</li><li>能跑通一个 LoRA 微调并解释超参</li><li>能自己写一个 FastAPI 的流式接口</li></ul><p>达到这四条，Python 这一章就过关了。</p>',21)])])}const h=t(a,[["render",i]]);export{u as __pageData,h as default};
